{"turn":1,"units":[
{"unitId":"blue-1","x":1960,"y":1680,"facingDeg":0,"formation":"line","strength":600,"morale":80,"fatigue":0,"ammo":100,"status":"active","continuing":{"kind":"hold"},"orders":[],"account":"Col. Aubry has no order and holds his line south of the river, facing the bridge. Towards the end of the turn he sights an enemy column halted on the road some 590 m to the north and keeps his men quiet."},
{"unitId":"blue-2","x":2140,"y":1680,"facingDeg":0,"formation":"line","strength":550,"morale":75,"fatigue":0,"ammo":100,"status":"active","continuing":{"kind":"hold"},"orders":[],"account":"Col. Delacroix has no order and keeps his line beside the 1st Battalion. He sights an enemy column on the road to the north, halted, and waits to see what it does."},
{"unitId":"blue-3","x":2050,"y":1850,"facingDeg":0,"formation":"line","strength":200,"morale":85,"fatigue":0,"ammo":100,"status":"active","continuing":{"kind":"hold"},"orders":[],"account":"Maj. Verneuil has no order and stays behind the infantry. He sights an enemy column on the road, a kilometre away at most, and reports it, but does not move without orders."},
{"unitId":"red-1","x":2050,"y":1100,"facingDeg":180,"formation":"column","strength":650,"morale":80,"fatigue":5,"ammo":100,"status":"active","continuing":{"kind":"hold"},"orders":[{"orderId":"r1-1","result":"carried-out"}],"account":"Col. Brandt gets his order at about the second minute and marches his battalion south down the high road in column. He halts at about the fifth minute, 400 paces (about 300 m) short of the river, as he was told. He sees the enemy line beyond the river at about 590 m and holds there, eager to go on."},
{"unitId":"red-2","x":2050,"y":860,"facingDeg":180,"formation":"column","strength":650,"morale":70,"fatigue":5,"ammo":100,"status":"active","continuing":{"kind":"hold"},"orders":[{"orderId":"r2-1","result":"carried-out"}],"account":"Col. Hartmann gets his order at about the third minute and follows the Vanguard down the road, by the book, keeping 300 paces (about 225 m) behind it. When the Vanguard halts he halts behind it, and waits for orders."},
{"unitId":"red-3","x":1550,"y":400,"facingDeg":180,"formation":"line","strength":220,"morale":85,"fatigue":0,"ammo":100,"status":"active","continuing":{"kind":"hold"},"orders":[],"account":"Maj. von Reiter has no order and holds his position at the edge of the northern wood."}
],
